package dev.pocketengine.features.local.project;
import static org.junit.Assert.*;
import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.nio.file.attribute.FileTime;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.json.*;import org.junit.*;
public final class ProjectDirectoryQueryTest {
 private Path root;private static final String CHECKOUT="11111111-1111-1111-1111-111111111111";
 @Before public void create()throws Exception{root=Files.createTempDirectory("pw-directory-list-");}
 @After public void close()throws Exception{try(var paths=Files.walk(root)){for(Path path:paths.sorted(Comparator.reverseOrder()).toArray(Path[]::new))Files.deleteIfExists(path);}}
 private JSONObject list(JSONObject input)throws Exception{return ProjectDirectoryQuery.list(root.toFile(),CHECKOUT,input,()->{});}
 @Test public void pagesContainActualDirectFilesAndEmptyDirectoriesWithoutReadingBodies()throws Exception{Files.createDirectory(root.resolve("empty"));Files.createDirectory(root.resolve("sub"));Files.write(root.resolve("sub/not-recursive.txt"),new byte[]{1});Files.write(root.resolve("binary.bin"),new byte[]{0,(byte)255});JSONObject first=list(new JSONObject().put("limit",2));assertEquals(3,first.getInt("totalEligibleEntries"));assertEquals("binary.bin",first.getJSONArray("entries").getJSONObject(0).getString("path"));assertEquals(2,first.getJSONArray("entries").getJSONObject(0).getInt("bytes"));assertEquals("directory",first.getJSONArray("entries").getJSONObject(1).getString("entryKind"));assertTrue(first.getJSONArray("entries").getJSONObject(1).isNull("bytes"));assertFalse(first.getBoolean("fileBodiesRead"));assertFalse(first.getBoolean("contentVersionVerified"));assertFalse(first.getBoolean("atomicReadFence"));JSONObject last=list(new JSONObject().put("limit",2).put("cursor",first.getJSONObject("nextCursor")));assertEquals(1,last.getJSONArray("entries").length());assertEquals("sub",last.getJSONArray("entries").getJSONObject(0).getString("path"));assertTrue(last.getBoolean("complete"));assertTrue(last.isNull("nextCursor"));assertEquals(1,list(new JSONObject().put("path","sub")).getJSONArray("entries").length());}
 @Test public void hiddenAndDependenciesRemainExcludedAndLinksNeverFollowed()throws Exception{Files.createDirectory(root.resolve(".git"));Files.createDirectory(root.resolve("node_modules"));Files.createDirectory(root.resolve("build"));Files.createDirectory(root.resolve(".hidden"));Files.createSymbolicLink(root.resolve("link"),root.resolve(".hidden"));JSONObject result=list(new JSONObject());assertEquals(0,result.getJSONArray("entries").length());assertEquals(3,result.getJSONObject("omitted").getInt("dependency_or_build"));assertEquals(1,result.getJSONObject("omitted").getInt("hidden"));assertEquals(1,result.getJSONObject("omitted").getInt("symlink"));assertFalse(result.getBoolean("coverageComplete"));assertEquals(1,list(new JSONObject().put("hidden",true)).getJSONArray("entries").length());assertThrows(SecurityException.class,()->list(new JSONObject().put("path","link")));assertThrows(SecurityException.class,()->list(new JSONObject().put("path",".hidden")));assertThrows(SecurityException.class,()->list(new JSONObject().put("path","node_modules").put("hidden",true)));}
 @Test public void staleOrAlteredCursorCannotJoinDifferentScopesOrMetadataVersions()throws Exception{Files.write(root.resolve("a"),new byte[]{1});Files.write(root.resolve("b"),new byte[]{2});JSONObject first=list(new JSONObject().put("limit",1));JSONObject cursor=first.getJSONObject("nextCursor");assertThrows(SecurityException.class,()->list(new JSONObject().put("limit",2).put("cursor",cursor)));assertThrows(SecurityException.class,()->list(new JSONObject().put("limit",1).put("hidden",true).put("cursor",cursor)));assertThrows(SecurityException.class,()->ProjectDirectoryQuery.list(root.toFile(),UUID.randomUUID().toString(),new JSONObject().put("limit",1).put("cursor",cursor),()->{}));assertThrows(SecurityException.class,()->list(new JSONObject().put("limit",1).put("cursor",new JSONObject(cursor.toString()).put("afterPath","not-present"))));Files.write(root.resolve("b"),new byte[]{3,4});assertThrows(SecurityException.class,()->list(new JSONObject().put("limit",1).put("cursor",cursor)));}
 @Test public void unsafeInputsMissingDirectoriesAndNonDirectoriesAreErrorsNotEmptyResults()throws Exception{Files.write(root.resolve("file"),new byte[]{1});for(String path:new String[]{"../escape","/etc",".","a//b","bad\\name"})assertThrows(Exception.class,()->list(new JSONObject().put("path",path)));assertThrows(NoSuchFileException.class,()->list(new JSONObject().put("path","missing")));assertThrows(IllegalArgumentException.class,()->list(new JSONObject().put("path","file")));for(Object limit:new Object[]{0,41,1.5,"1",JSONObject.NULL})assertThrows(Exception.class,()->list(new JSONObject().put("limit",limit)));assertThrows(IllegalArgumentException.class,()->list(new JSONObject().put("hidden","yes")));assertThrows(IllegalArgumentException.class,()->list(new JSONObject().put("body",true)));}
 @Test public void resultBudgetPaginatesUnicodePathsWithoutLosingEntriesOrZeroProgress()throws Exception{for(int i=0;i<70;i++)Files.write(root.resolve(String.format("%03d",i)+"中".repeat(70)),new byte[]{1});Set<String> seen=new TreeSet<>();JSONObject input=new JSONObject();int pages=0;do{JSONObject result=list(input);assertTrue(result.toString().getBytes(StandardCharsets.UTF_8).length<=ProjectDirectoryQuery.MAX_RESULT_BYTES);JSONArray rows=result.getJSONArray("entries");assertTrue(rows.length()>0);for(int i=0;i<rows.length();i++)assertTrue(seen.add(rows.getJSONObject(i).getString("path")));pages++;if(result.getBoolean("complete"))break;input.put("cursor",result.getJSONObject("nextCursor"));}while(pages<10);assertEquals(70,seen.size());assertTrue(pages>=3);}
 @Test public void metadataDriftBetweenTwoScansAndCancellationDoNotReturnMixedPages()throws Exception{Files.write(root.resolve("a"),new byte[]{1});AtomicInteger count=new AtomicInteger();ProjectDirectoryQuery.list(root.toFile(),CHECKOUT,new JSONObject(),count::incrementAndGet);int mutate=count.get()/2+1;AtomicInteger calls=new AtomicInteger();assertThrows(SecurityException.class,()->ProjectDirectoryQuery.list(root.toFile(),CHECKOUT,new JSONObject(),()->{if(calls.incrementAndGet()==mutate)Files.write(root.resolve("a"),new byte[]{2,3});}));assertThrows(InterruptedException.class,()->ProjectDirectoryQuery.list(root.toFile(),CHECKOUT,new JSONObject(),()->{throw new InterruptedException("cancelled original");}));}
 @Test public void enumerationLimitAlsoCountsExcludedNamesRatherThanExpandingHiddenSweeps()throws Exception{for(int i=0;i<=ProjectDirectoryQuery.MAX_ENTRIES;i++)Files.write(root.resolve(".excluded"+i),new byte[0]);assertThrows(IllegalArgumentException.class,()->list(new JSONObject()));}
 @Test public void emptyDirectoryIsAnObservedCompleteEmptyPageNotAFakeMissingFile()throws Exception{JSONObject result=list(new JSONObject());assertTrue(result.getBoolean("complete"));assertTrue(result.getBoolean("coverageComplete"));assertEquals(0,result.getJSONArray("entries").length());assertTrue(result.isNull("nextCursor"));assertEquals(0,result.getInt("examinedEntries"));assertEquals(2,result.getInt("metadataScans"));}
}
